<template><div class="reviews"><header><h1>人工复核工作台</h1><div class="auth"><el-input v-model="token" type="password" show-password placeholder="管理令牌"/><el-input v-model="reviewer" placeholder="审核员名称"/><el-button type="primary" @click="connect">连接</el-button></div></header><el-alert v-if="error" type="error" :closable="false" :description="error"/><el-card v-if="connected"><template #header>复核指标</template><div class="stats"><div class="stat"><strong>{{ stats.pending }}</strong><span>待处理</span></div><div class="stat"><strong>{{ stats.claimed }}</strong><span>处理中</span></div><div class="stat"><strong>{{ stats.resolved }}</strong><span>已结案</span></div><div class="stat"><strong>{{ (stats.false_positive_rate*100).toFixed(1) }}%</strong><span>误报率</span></div><div class="stat"><strong>{{ stats.candidates_pending }} / {{ stats.candidates_applied }}</strong><span>候选 待处理/已应用</span></div></div><table v-if="stats.reviewers.length" class="reviewer-table"><thead><tr><th>审核员</th><th>结案</th><th>确认违规</th><th>误报</th><th>漏报</th><th>平均耗时</th></tr></thead><tbody><tr v-for="r in stats.reviewers" :key="r.reviewer"><td>{{ r.reviewer }}</td><td>{{ r.resolved }}</td><td>{{ r.confirmed_violation }}</td><td>{{ r.false_positive }}</td><td>{{ r.false_negative }}</td><td>{{ formatDuration(r.avg_handle_seconds) }}</td></tr></tbody></table></el-card><el-card v-if="connected"><template #header>提交复核</template><div class="form"><el-select v-model="policyId"><el-option v-for="p in policies" :key="p.id" :label="`${p.name} v${p.version}`" :value="p.id"/></el-select><el-input v-model="text" type="textarea" :rows="4"/><el-button type="primary" @click="create">检测并提交</el-button></div></el-card><el-card v-if="connected"><template #header>复核队列</template><article v-for="task in tasks" :key="task.id" class="row"><div><strong>{{ task.status }} · 风险 {{ task.risk_score }} · {{ task.recommended_action }}</strong><p>{{ task.text }}</p><small>{{ task.claimed_by||'未领取' }} · {{ task.conclusion||'待结论' }}</small></div><div class="actions"><el-button v-if="task.status==='pending'" @click="claim(task.id)">领取</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" @click="release(task.id)">释放</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" type="success" @click="resolve(task,'confirmed_violation')">确认违规</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" @click="resolve(task,'false_positive')">误报</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" type="warning" @click="resolve(task,'false_negative')">漏报</el-button></div></article><el-empty v-if="!tasks.length" description="暂无复核任务"/></el-card><el-card v-if="connected"><template #header>反馈候选</template><div v-for="item in candidates" :key="item.id" class="candidate"><el-tag>{{ item.type }}</el-tag><span>{{ item.value }}</span><small>{{ item.category||'全类别' }} · {{ item.status }}</small><span v-if="item.status==='pending'&&['whitelist','wordlist'].includes(item.type)" class="actions"><el-button size="small" type="success" @click="applyCandidate(item.id)">{{ item.type==='whitelist'?'应用为白名单':'加入词库' }}</el-button><el-button size="small" @click="dismissCandidate(item.id)">忽略</el-button></span></div><el-empty v-if="!candidates.length" description="暂无反馈候选"/></el-card></div></template>
<script setup>
import{ref}from'vue';import{applyFeedbackCandidate,claimReviewTask,createReviewTask,describeAPIError,dismissFeedbackCandidate,fetchFeedbackCandidates,fetchPlatformPolicies,fetchReviewStats,fetchReviewTasks,releaseReviewTask,resolveReviewTask}from'@/services/api';defineOptions({name:'HumanReviews'});const token=ref(sessionStorage.getItem('sensitive_admin_token')||''),reviewer=ref(sessionStorage.getItem('sensitive_reviewer')||''),connected=ref(false),error=ref(''),policies=ref([]),policyId=ref('default'),text=ref(''),tasks=ref([]),candidates=ref([]),stats=ref({pending:0,claimed:0,resolved:0,false_positive_rate:0,candidates_pending:0,candidates_applied:0,reviewers:[]});const formatDuration=s=>{const m=Math.round(s/60);return m<1?'<1 分钟':`${m} 分钟`};const report=e=>error.value=describeAPIError(e).message;const refresh=async()=>{const[t,c,s]=await Promise.all([fetchReviewTasks(token.value),fetchFeedbackCandidates(token.value),fetchReviewStats(token.value)]);tasks.value=t.items||[];candidates.value=c.items||[];stats.value=s||stats.value};const connect=async()=>{sessionStorage.setItem('sensitive_admin_token',token.value);sessionStorage.setItem('sensitive_reviewer',reviewer.value);try{policies.value=(await fetchPlatformPolicies(token.value)).items||[];connected.value=true;await refresh()}catch(e){report(e)}};const create=async()=>{try{await createReviewTask(token.value,{policy_id:policyId.value,text:text.value});text.value='';await refresh()}catch(e){report(e)}};const claim=async id=>{try{await claimReviewTask(token.value,id,reviewer.value);await refresh()}catch(e){report(e)}};const release=async id=>{try{await releaseReviewTask(token.value,id,reviewer.value);await refresh()}catch(e){report(e)}};const resolve=async(task,conclusion)=>{const value=conclusion==='false_positive'?prompt('白名单候选短语',task.text):conclusion==='false_negative'?prompt('漏报词条',''):'';try{await resolveReviewTask(token.value,task.id,{reviewer:reviewer.value,conclusion,note:'控制台复核',candidate_type:conclusion==='false_positive'?'whitelist':conclusion==='false_negative'?'wordlist':'',value:value||''});await refresh()}catch(e){report(e)}};const applyCandidate=async id=>{try{await applyFeedbackCandidate(token.value,id);await refresh()}catch(e){report(e)}};const dismissCandidate=async id=>{try{await dismissFeedbackCandidate(token.value,id);await refresh()}catch(e){report(e)}}
</script><style scoped>.reviews{display:flex;flex-direction:column;gap:18px}.reviews header,.auth,.actions,.candidate{display:flex;align-items:center;justify-content:space-between;gap:10px}.auth{width:min(650px,100%)}.form{display:flex;flex-direction:column;gap:10px}.row{display:grid;grid-template-columns:1fr auto;gap:12px;padding:12px 0;border-bottom:1px solid var(--border-subtle)}.row p{white-space:pre-wrap}.row small,.candidate small{color:var(--text-sub)}.actions{flex-wrap:wrap}.candidate{justify-content:flex-start;padding:8px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.stat{display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px;border:1px solid var(--border-subtle);border-radius:8px}.stat strong{font-size:20px}.stat span{color:var(--text-sub);font-size:12px}.reviewer-table{width:100%;margin-top:12px;border-collapse:collapse}.reviewer-table th,.reviewer-table td{padding:6px 10px;text-align:left;border-bottom:1px solid var(--border-subtle)}@media(max-width:760px){.reviews header,.auth{flex-direction:column;align-items:stretch}.row{grid-template-columns:1fr}}</style>
